extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var rock := main.get_node_or_null("GiantRock") as Node3D
	if check("rock_exists", rock != null, "La scena deve contenere GiantRock"):
		check("rock_scale", rock.scale.distance_to(Vector3(0.2, 0.2, 0.2)) < 0.05, "GiantRock deve avere scala (0.2, 0.2, 0.2) (è %s)" % str(rock.scale))
	var col := main.get_node_or_null("FallenColumn") as Node3D
	if check("col_exists", col != null, "La scena deve contenere FallenColumn"):
		check("col_rot", absf(col.rotation_degrees.z) < 0.1, "FallenColumn deve avere rotation_degrees.z = 0 (è %.1f)" % col.rotation_degrees.z)
	var statue_mesh := main.get_node_or_null("UncoloredStatue/MeshInstance3D") as MeshInstance3D
	if check("statue_exists", statue_mesh != null, "UncoloredStatue deve avere un figlio MeshInstance3D"):
		var mat = statue_mesh.material_override as StandardMaterial3D
		check("statue_mat", mat != null, "MeshInstance3D deve avere un StandardMaterial3D assegnato a material_override")
		if mat != null:
			check("statue_color", mat.albedo_color.b > 0.5, "Il materiale della statua deve avere un colore albedo blu")
